test("REQ-1: invalid grade throws RangeError", () => {
  assert.throws(() => scheduleReview({ reps: 0, interval: 1, ease: 2.5 }, 6, 1000000), RangeError);
  assert.throws(() => scheduleReview({ reps: 0, interval: 1, ease: 2.5 }, -1, 1000000), RangeError);
});

test("REQ-2: grade 4 advances repetitions and expands interval", () => {
  const c1 = scheduleReview({ reps: 0, interval: 1, ease: 2.5 }, 4, 1000000);
  assert.equal(c1.reps, 1);
  assert.equal(c1.interval, 1);
  const c2 = scheduleReview(c1, 4, 1000000);
  assert.equal(c2.reps, 2);
  assert.equal(c2.interval, 6);
});

test("REQ-3 REQ-4: lapse resets reps and bounds ease at 1.30", () => {
  const c = scheduleReview({ reps: 3, interval: 12, ease: 1.35, lapses: 0 }, 1, 1000000);
  assert.equal(c.reps, 0);
  assert.equal(c.interval, 1);
  assert.equal(c.lapses, 1);
  assert.ok(c.ease >= 1.3);
});

test("REQ-5: lapses >= 8 flags card as leech", () => {
  const c = scheduleReview({ reps: 1, interval: 1, ease: 2.5, lapses: 7 }, 2, 1000000);
  assert.equal(c.leech, true);
});

