export interface CardState {
  reps: number;
  interval: number;
  ease: number;
  lapses?: number;
  due?: number;
  leech?: boolean;
}

const MIN_EASE = 1.3;
const LEECH_THRESHOLD = 8;
const DAY_MS = 86400000;

export function updateEase(ease: number, grade: number): number {
  const next = ease + (0.1 - (5 - grade) * (0.08 + (5 - grade) * 0.02));
  return Math.max(MIN_EASE, Math.round(next * 100) / 100);
}

export function scheduleReview(card: CardState, grade: number, now: number): CardState {
  if (!Number.isInteger(grade) || grade < 0 || grade > 5) {
    throw new RangeError("grade must be an integer 0-5");
  }
  const next: CardState = { ...card };
  if (grade >= 3) {
    next.interval = card.reps === 0 ? 1 : card.reps === 1 ? 6 : Math.round(card.interval * card.ease);
    next.reps = card.reps + 1;
  } else {
    next.reps = 0;
    next.interval = 1;
    next.lapses = (card.lapses || 0) + 1;
  }
  next.ease = updateEase(card.ease, grade);
  next.due = now + next.interval * DAY_MS;
  next.leech = (next.lapses || 0) >= LEECH_THRESHOLD;
  return next;
}
